import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as a,e as s}from"./app-4490560f.js";const t={},i=s(`<h1 id="latexindent-latex-文件自动缩进-格式化工具" tabindex="-1"><a class="header-anchor" href="#latexindent-latex-文件自动缩进-格式化工具" aria-hidden="true">#</a> latexindent（LaTeX 文件自动缩进/格式化工具）</h1><blockquote><p>Homebrew 版本 3.24.7 ｜ 主页：见官方文档 ｜ 安装：<code>brew install latexindent</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>latexindent 是一个专门用于 LaTeX 源文件的自动缩进与格式化工具，它根据 LaTeX 的环境、命令、括号嵌套层级和代码注释，自动把混乱的 <code>.tex</code> 源文件整理成统一、清晰、易读的排版结构。它能解决&quot;手写 LaTeX 缩进不规范、多人协作格式混乱、从编辑器复制粘贴后排版错乱&quot;这类痛点，非常适合在提交代码前格式化、批量整理旧文档、或配合编辑器保存时自动整理使用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> latexindent

<span class="token comment"># 升级</span>
brew upgrade latexindent

<span class="token comment"># 卸载</span>
brew uninstall latexindent

<span class="token comment"># 验证安装成功（查看版本号）</span>
latexindent <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装成功后，终端输入 <code>latexindent -h</code> 可查看帮助信息。它会附带安装 Perl 及若干依赖模块（如 <code>YAML::Tiny</code>、<code>File::HomeDir</code> 等），首次运行时无需额外配置。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>latexindent &lt;file&gt;</code></td><td>格式化指定文件，结果输出到 <code>&lt;file-indent.log&gt;</code>（默认不覆盖原文件）</td><td><code>latexindent main.tex</code></td></tr><tr><td><code>-w</code> / <code>--overwrite</code></td><td>覆盖写入原文件（原地格式化）</td><td><code>latexindent -w main.tex</code></td></tr><tr><td><code>-o &lt;outfile&gt;</code></td><td>把结果输出到指定文件</td><td><code>latexindent -o formatted.tex main.tex</code></td></tr><tr><td><code>-s</code> / <code>--silent</code></td><td>静默模式，抑制日志输出</td><td><code>latexindent -s -w main.tex</code></td></tr><tr><td><code>-l &lt;yaml&gt;</code> / <code>--local</code></td><td>使用自定义配置文件（localSettings YAML）</td><td><code>latexindent -l my.tex</code></td></tr><tr><td><code>-m</code> / <code>--modifylinebreaks</code></td><td>修改断行（配合 <code>-l</code> 设置的文件行宽）</td><td><code>latexindent -m -l my.tex main.tex</code></td></tr><tr><td><code>-r</code> / <code>--replacement</code></td><td>配合 <code>-m</code> 使用，允许替换旧文档的断行方式</td><td><code>latexindent -m -r -w main.tex</code></td></tr><tr><td><code>-g &lt;log&gt;</code> / <code>--logfile</code></td><td>指定日志文件路径</td><td><code>latexindent -g fmt.log main.tex</code></td></tr><tr><td><code>-c &lt;dir&gt;</code></td><td>指定操作目录（方便批量处理多个文件）</td><td><code>latexindent -c src main.tex</code></td></tr><tr><td><code>-t</code> / <code>--trace</code></td><td>输出详细调试追踪信息</td><td><code>latexindent -t -w main.tex</code></td></tr><tr><td><code>-vv</code></td><td>显示 verbose 级日志</td><td><code>latexindent -vv -w main.tex</code></td></tr></tbody></table><blockquote><p>提示：不带 <code>-w</code> 时 latexindent <strong>不会修改原文件</strong>，结果写入 <code>&lt;文件名&gt;-indent.log</code> 中，方便先检查效果再决定是否覆盖。</p></blockquote><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-格式化单个文件并预览结果" tabindex="-1"><a class="header-anchor" href="#示例-1-格式化单个文件并预览结果" aria-hidden="true">#</a> 示例 1：格式化单个文件并预览结果</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备一个缩进混乱的测试文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> messy.tex <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
\\documentclass{article}
\\begin{document}
\\begin{itemize}
\\item 苹果
\\item 香蕉
\\begin{enumerate}
\\item 子项一
\\item 子项二
\\end{enumerate}
\\end{itemize}
\\end{document}
EOF</span>

<span class="token comment"># 格式化（不覆盖原文件，结果写到 messy-indent.log）</span>
latexindent messy.tex

<span class="token comment"># 查看格式化结果</span>
<span class="token function">cat</span> messy-indent.log
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后 <code>messy-indent.log</code> 中每个环境内的内容会正确缩进，<code>\\item</code> 与嵌套环境层级清晰。</p><h3 id="示例-2-原地覆盖格式化并静默处理" tabindex="-1"><a class="header-anchor" href="#示例-2-原地覆盖格式化并静默处理" aria-hidden="true">#</a> 示例 2：原地覆盖格式化并静默处理</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接覆盖原文件，且不输出多余日志</span>
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-w</span> messy.tex

<span class="token comment"># 确认文件已被改写</span>
<span class="token function">cat</span> messy.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>-s</code> 抑制日志、<code>-w</code> 原地写回，两者组合适合在脚本或编辑器保存钩子里调用。</p><h3 id="示例-3-用自定义配置控制缩进宽度与换行" tabindex="-1"><a class="header-anchor" href="#示例-3-用自定义配置控制缩进宽度与换行" aria-hidden="true">#</a> 示例 3：用自定义配置控制缩进宽度与换行</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 编写自定义配置 localSettings.yaml</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> localSettings.yaml <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;</span>
indentAfterItems:
    - enumerate
    - itemize
defaultIndent: <span class="token string">&quot;    &quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 使用配置格式化（-m 按配置调整断行，-w 覆盖原文件）</span>
latexindent <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>自定义 YAML 中可设置默认缩进、是否在列表项后缩进、环境放行/排除规则、替换文件头（preamble）等大量参数，实现项目级统一的格式规范。</p><h3 id="示例-4-批量格式化目录下的所有-tex-文件" tabindex="-1"><a class="header-anchor" href="#示例-4-批量格式化目录下的所有-tex-文件" aria-hidden="true">#</a> 示例 4：批量格式化目录下的所有 .tex 文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 对 src 目录下所有 .tex 文件逐个原地格式化</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">f</span> <span class="token keyword">in</span> src/*.tex<span class="token punctuation">;</span> <span class="token keyword">do</span>
    latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-w</span> <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span>
<span class="token keyword">done</span>

<span class="token comment"># 或使用 -c 指定目录</span>
latexindent <span class="token parameter variable">-c</span> src <span class="token parameter variable">-s</span> <span class="token parameter variable">-w</span> src/main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>批量处理时注意：不带 <code>-w</code> 会在每个文件旁生成 <code>.indent.log</code>，正式提交前可用 <code>git diff</code> 检查改动。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_5-1-配置文件位置与加载优先级" tabindex="-1"><a class="header-anchor" href="#_5-1-配置文件位置与加载优先级" aria-hidden="true">#</a> 5.1 配置文件位置与加载优先级</h3><p>latexindent 按<strong>从低到高</strong>的优先级合并配置，后者覆盖前者：</p><ol><li>内建 <code>defaultSettings.yaml</code>（安装目录中的默认值）；</li><li>用户级 <code>~/.indentconfig.yaml</code>（或 <code>~/.latexindent.yaml</code>），对所有项目生效；</li><li>项目级 <code>localSettings.yaml</code>（当前目录），通过 <code>-l</code> 显式指定，或在当前目录自动发现。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看本机内建默认配置（可作为个性化起点，参考其所有可用键）</span>
latexindent <span class="token parameter variable">--defaults</span> <span class="token operator">|</span> <span class="token function">less</span>
<span class="token comment"># 或直接查看安装位置的原始文件</span>
<span class="token function">less</span> <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span>brew <span class="token parameter variable">--prefix</span> latexindent<span class="token variable">)</span></span>&quot;</span>/defaultSettings.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>defaultSettings.yaml</code> 是唯一权威的&quot;完整键表&quot;。个人配置只需写想覆盖的键即可，未写到的仍取默认值。</p></blockquote><h3 id="_5-2-一份可直接使用的个性化配置" tabindex="-1"><a class="header-anchor" href="#_5-2-一份可直接使用的个性化配置" aria-hidden="true">#</a> 5.2 一份可直接使用的个性化配置</h3><p>把下面的内容存成 <code>~/.indentconfig.yaml</code>（对所有项目生效）或项目根目录的 <code>localSettings.yaml</code>：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># 缩进基础</span>
<span class="token key atrule">defaultIndent</span><span class="token punctuation">:</span> <span class="token string">&quot;  &quot;</span>                    <span class="token comment"># 两级空格缩进</span>
<span class="token key atrule">indentAfterItems</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>                    <span class="token comment"># 列表项后不再额外缩进（紧凑风格）</span>

<span class="token comment"># 命名规则与放行环境</span>
<span class="token key atrule">lookForAlignDelims</span><span class="token punctuation">:</span>
    <span class="token key atrule">tabular</span><span class="token punctuation">:</span>
        <span class="token key atrule">alignDoubleBackSlash</span><span class="token punctuation">:</span> <span class="token number">1</span>         <span class="token comment"># 表格中对齐 &amp; 分隔</span>
    <span class="token key atrule">matrix</span><span class="token punctuation">:</span>
        <span class="token key atrule">alignDoubleBackSlash</span><span class="token punctuation">:</span> <span class="token number">1</span>

<span class="token comment"># 断行控制（modifylinebreaks）</span>
<span class="token key atrule">modifyLineBreaks</span><span class="token punctuation">:</span>
    <span class="token key atrule">preserveBlankLines</span><span class="token punctuation">:</span> <span class="token number">1</span>
    <span class="token key atrule">condenseMultipleBlankLinesInto</span><span class="token punctuation">:</span> <span class="token number">0</span>   <span class="token comment"># 不合并连续空行</span>
    <span class="token key atrule">removeSentenceLineBreaks</span><span class="token punctuation">:</span> <span class="token number">0</span>         <span class="token comment"># 保持中文/句子的手动换行不被改动</span>
    <span class="token key atrule">oneSentencePerLine</span><span class="token punctuation">:</span> <span class="token number">0</span>               <span class="token comment"># 不强制每句一行（对中文长句尤其重要）</span>

<span class="token comment"># 放行环境 / 排除环境</span>
<span class="token key atrule">noAdditionalIndent</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> verbatim
    <span class="token punctuation">-</span> lstlisting
    <span class="token punctuation">-</span> minted
    <span class="token punctuation">-</span> equation
    <span class="token punctuation">-</span> align

<span class="token comment"># 允许 latexindent 在找不到匹配时也尝试缩进</span>
<span class="token key atrule">alwaysLookforHit</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：<code>removeSentenceLineBreaks: 0</code> 和 <code>oneSentencePerLine: 0</code> 对<strong>中文/混排文档</strong>是保命选项——latexindent 默认会尝试合并行，中文断句规则不同，极易把注释或句段拼错行，务必显式关闭。</p></blockquote><h3 id="_5-3-常用配置键速查表" tabindex="-1"><a class="header-anchor" href="#_5-3-常用配置键速查表" aria-hidden="true">#</a> 5.3 常用配置键速查表</h3><table><thead><tr><th>配置键</th><th>作用</th><th>常用取值</th></tr></thead><tbody><tr><td><code>defaultIndent</code></td><td>默认缩进字符串</td><td><code>&quot; &quot;</code> 或 <code>&quot;\\t&quot;</code>（用制表符）</td></tr><tr><td><code>indentAfterItems</code></td><td>列表项(<code>\\item</code>)后是否缩进</td><td><code>[]</code>（不缩）或 <code>[enumerate,itemize]</code></td></tr><tr><td><code>noAdditionalIndent</code></td><td>这些环境不再额外缩进</td><td>数组，如 <code>[verbatim,equation]</code></td></tr><tr><td><code>alwaysLookforHit</code></td><td>找不到括号匹配时也缩进</td><td><code>1</code> / <code>0</code></td></tr><tr><td><code>modifyLineBreaks.preserveBlankLines</code></td><td>保留空行</td><td><code>1</code> / <code>0</code></td></tr><tr><td><code>modifyLineBreaks.removeSentenceLineBreaks</code></td><td>是否合并句间换行</td><td><code>1</code> / <code>0</code></td></tr><tr><td><code>modifyLineBreaks.oneSentencePerLine</code></td><td>每句独立一行</td><td><code>1</code> / <code>0</code></td></tr><tr><td><code>lookForAlignDelims</code></td><td>表格/矩阵对齐 <code>&amp;</code> 与 <code>\\\\</code></td><td>见官方文档</td></tr><tr><td><code>textWrapOptions</code></td><td>配合 <code>-m</code> 设定行宽折行</td><td><code>{columns: 80, ...}</code></td></tr></tbody></table><h3 id="_5-4-环境变量" tabindex="-1"><a class="header-anchor" href="#_5-4-环境变量" aria-hidden="true">#</a> 5.4 环境变量</h3><ul><li><code>LATEXINDENT_LOGFILE</code>：设置默认日志文件路径，代替每次敲 <code>-g</code>。</li><li><code>LATEXINDENT_LOCAL_SETTINGS</code>：指定默认的 localSettings 文件，代替 <code>-l</code>。</li><li><code>HOME</code> / <code>XDG_CONFIG_HOME</code>：影响用户级配置文件查找位置。</li><li><code>PERL5LIB</code>：自定义 Perl 库路径，用于指向额外安装的 <code>YAML::Tiny</code> 等模块（一般不需手动设置，Homebrew 已配好）。</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 示例：用环境变量固定配置与日志位置</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">LATEXINDENT_LOCAL_SETTINGS</span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>/dotfiles/latex/latexindent.yaml&quot;</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">LATEXINDENT_LOGFILE</span><span class="token operator">=</span><span class="token string">&quot;/tmp/latexindent.log&quot;</span>
latexindent <span class="token parameter variable">-m</span> <span class="token parameter variable">-w</span> main.tex        <span class="token comment"># 自动读上面配置，日志写到 /tmp/latexindent.log</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-5-与编辑器深度集成" tabindex="-1"><a class="header-anchor" href="#_5-5-与编辑器深度集成" aria-hidden="true">#</a> 5.5 与编辑器深度集成</h3><p><strong>Vim / Neovim</strong>（保存时自动格式化）：</p><div class="language-vim line-numbers-mode" data-ext="vim"><pre class="language-vim"><code><span class="token comment">&quot; ~/.vimrc 或 ~/.config/nvim/init.vim</span>
<span class="token builtin">autocmd</span> FileType tex <span class="token keyword">setlocal</span> <span class="token builtin">formatprg</span><span class="token operator">=</span>latexindent\\ <span class="token operator">-</span>s\\ <span class="token operator">-</span><span class="token keyword">t</span>
<span class="token builtin">autocmd</span> BufWritePre <span class="token operator">*</span><span class="token operator">.</span>tex <span class="token keyword">silent</span><span class="token operator">!</span> execute <span class="token string">&#39;%! latexindent -s -t -g /dev/null&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：<code>%!</code> 是把当前缓冲区内容通过管道交给外部命令再写回。<code>-t</code> 生成 trace 日志便于排查，生产可去掉。若想用项目级配置，把 <code>-s</code> 换成 <code>-s -m -l localSettings.yaml</code>。</p></blockquote><p><strong>VS Code</strong>：配合 <code>LaTeX Workshop</code> 扩展，在其 <code>settings.json</code> 中：</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;latex-workshop.formatting.latex&quot;</span><span class="token operator">:</span> <span class="token string">&quot;latexindent&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;latex-workshop.formatting.latex.args&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span>
    <span class="token string">&quot;-l&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;%DIR%/localSettings.yaml&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;-c&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;%DIR%/&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;%TMPFILE%&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;-o&quot;</span><span class="token punctuation">,</span>
    <span class="token string">&quot;%TMPFILE%&quot;</span>
  <span class="token punctuation">]</span><span class="token punctuation">,</span>
  <span class="token property">&quot;[latex]&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;editor.formatOnSave&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Sublime Text</strong>：用 LaTeXing 等包的 <code>latexindent</code> 命令，绑定 <code>alt+shift+f</code> 一键格式化。</p><h3 id="_5-6-检查改动而不是盲覆盖" tabindex="-1"><a class="header-anchor" href="#_5-6-检查改动而不是盲覆盖" aria-hidden="true">#</a> 5.6 检查改动而不是盲覆盖</h3><p>先在无 <code>-w</code> 模式下生成 <code>.indent.log</code>，用 <code>diff</code> 对比确认符合预期后再落盘：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml main.tex
<span class="token function">diff</span> main.tex main-indent.log   <span class="token comment"># 逐行查看差异</span>
<span class="token comment"># 确认无误后真正覆盖</span>
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_6-1-新手踩坑" tabindex="-1"><a class="header-anchor" href="#_6-1-新手踩坑" aria-hidden="true">#</a> 6.1 新手踩坑</h3><ol><li><p><strong>不覆盖原文件是默认行为</strong>：很多新手以为命令执行后文件已格式化，其实结果写在 <code>&lt;文件名&gt;-indent.log</code>。需要真正改文件务必加 <code>-w</code>（<code>--overwrite</code>）。</p></li><li><p><strong>忘记 <code>-l</code> 时项目配置不生效</strong>：默认不会自动读取项目级 <code>localSettings.yaml</code>，除非该文件就在当前目录且被自动发现。多目录项目建议始终显式 <code>-l</code>，避免不同子目录行为不一致。</p></li><li><p><strong>先跑通小文件再上大文件</strong>：新配置第一次使用，先在几十行的样例上跑一遍看效果，再应用到全书，否则错误的缩进规则会污染整个项目。</p></li><li><p><strong><code>-r</code> 必须搭配 <code>-m</code></strong>：<code>-r</code>（replacement）只与 <code>-m</code> 配合使用，用来替换旧断行方式；单独用 <code>-r</code> 可能无效或报参数错误。</p></li></ol><h3 id="_6-2-常见报错及解决办法" tabindex="-1"><a class="header-anchor" href="#_6-2-常见报错及解决办法" aria-hidden="true">#</a> 6.2 常见报错及解决办法</h3><table><thead><tr><th>报错 / 现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>Can&#39;t locate YAML/Tiny.pm</code></td><td>Perl 模块缺失（环境异常）</td><td><code>brew reinstall latexindent</code> 重新装依赖；或 <code>cpan YAML::Tiny File::HomeDir Unicode::GCString</code></td></tr><tr><td>中文乱码、注释被改写</td><td>源文件非 UTF-8 编码</td><td>先 <code>iconv -f GBK -t UTF-8 in.tex &gt; out.tex</code> 转码再处理</td></tr><tr><td>长中文句被合并成一行</td><td>默认句子断行规则不适合中文</td><td>配置 <code>modifyLineBreaks.removeSentenceLineBreaks: 0</code> 与 <code>oneSentencePerLine: 0</code></td></tr><tr><td><code>align</code> 等环境内部缩进被改坏</td><td><code>noAdditionalIndent</code> 未放行数学环境</td><td>在配置 <code>noAdditionalIndent</code> 里加入 <code>equation</code>、<code>align</code>、<code>gather</code> 等</td></tr><tr><td>生成大量 <code>.indent.log</code></td><td>批量处理未加 <code>-w</code></td><td>批量脚本统一加 <code>-s -w</code>，或每次清理 <code>find . -name &#39;*-indent.log&#39; -delete</code></td></tr><tr><td>处理时速度极慢</td><td>打开了 <code>-t</code> trace 或 <code>-vv</code></td><td>正式批处理用 <code>-s</code>，关掉追踪</td></tr></tbody></table><h3 id="_6-3-性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#_6-3-性能与安全注意点" aria-hidden="true">#</a> 6.3 性能与安全注意点</h3><ul><li><strong>大文件性能</strong>：处理几百 KB 到 MB 级的大型文档时，trace/verbose 模式会显著变慢，正式批处理建议用 <code>-s</code> 静默模式并关闭 <code>-t</code> 追踪。</li><li><strong>不要格式化算法/宏密集的片段</strong>：对包含大量复杂 <code>\\if...\\else</code>、自定义宏嵌套的代码，latexindent 可能调整其本不该动的断行。使用 <code>-m</code> 时要先 <code>diff</code> 检查，或利用 <code>modifyLineBreaks</code> 白名单/黑名单按需排除。</li><li><strong>进版控制前先看 diff</strong>：批量覆盖前用 <code>git diff --stat</code> 确认改动规模合理，防止把全项目几百行无谓重排带入提交。</li><li><strong>备份</strong>：涉及大规模历史文档重排，建议先 <code>git checkout</code> 一份或 <code>cp -r</code> 备份目录，再跑格式化。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-大型-latex-项目组织-多章节-主文档管理" tabindex="-1"><a class="header-anchor" href="#_7-1-大型-latex-项目组织-多章节-主文档管理" aria-hidden="true">#</a> 7.1 大型 LaTeX 项目组织（多章节 + 主文档管理）</h3><p>对大项目，常把文档拆成多个章节文件，用 <code>\\input</code> 或 <code>\\subfile</code> 组装，latexindent 逐文件处理但保持统一风格：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>book/
├── main.tex            # 主文档（\\input 或 \\subfile 引入各章节）
├── localSettings.yaml  # 项目级统一缩进配置
├── chapters/
│   ├── intro.tex
│   ├── method.tex
│   └── conclusion.tex
└── figures/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 一次性格式化主文档 + 所有章节，全用同一份项目配置</span>
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> main.tex chapters/*.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：用 <code>\\subfile</code> 的项目，<code>main.tex</code> 里 <code>\\input</code> 路径与各子文件 <code>\\subfile{}</code> 的路径结构不同，latexindent 不解析跨文件，只逐文件格式化，无需特殊处理。</p></blockquote><h3 id="_7-2-书目管理-bibtex-biblatex" tabindex="-1"><a class="header-anchor" href="#_7-2-书目管理-bibtex-biblatex" aria-hidden="true">#</a> 7.2 书目管理（bibtex / biblatex）</h3><p>latexindent 只格式化 <code>.tex</code>，书目 <code>.bib</code> 用专门工具（如 <code>bibtool</code>、<code>bibtex-tidy</code>）。在自动化脚本里把它们串联：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先整理 bib 引用，再格式化正文</span>
bibtex-tidy <span class="token parameter variable">--omit</span><span class="token operator">=</span>abstract,file note refs.bib <span class="token parameter variable">-o</span> refs.tidy.bib <span class="token operator">&amp;&amp;</span> <span class="token function">mv</span> refs.tidy.bib refs.bib
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-图表目录与浮动体" tabindex="-1"><a class="header-anchor" href="#_7-3-图表目录与浮动体" aria-hidden="true">#</a> 7.3 图表目录与浮动体</h3><p>表格/浮动体建议用 <code>lookForAlignDelims.tabular</code> 对齐 <code>&amp;</code>，并在格式化后检查对齐结果：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 强制对齐 tabular 中的 &amp; 与 \\\\</span>
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> tables/data-table.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-makefile-自动化" tabindex="-1"><a class="header-anchor" href="#_7-4-makefile-自动化" aria-hidden="true">#</a> 7.4 Makefile 自动化</h3><p>把格式化、清理、编译串成目标，纳入日常构建：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile（顶层）</span>
LATEXINDENT <span class="token operator">?=</span> latexindent
INDENT_ARGS <span class="token operator">?=</span> -s -m -l localSettings.yaml
TEXFILES <span class="token operator">:=</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">shell</span> find . -name <span class="token string">&#39;*.tex&#39;</span> -not -path <span class="token string">&#39;./build/*&#39;</span><span class="token punctuation">)</span>

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> fmt clean pdf

<span class="token target symbol">fmt</span><span class="token punctuation">:</span>                      <span class="token comment"># 统一格式化所有 .tex</span>
	<span class="token variable">$</span><span class="token punctuation">(</span>LATEXINDENT<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>INDENT_ARGS<span class="token punctuation">)</span> -w <span class="token variable">$</span><span class="token punctuation">(</span>TEXFILES<span class="token punctuation">)</span>

<span class="token target symbol">clean-log</span><span class="token punctuation">:</span>                <span class="token comment"># 清理格式化产生的日志</span>
	find . -name <span class="token string">&#39;*-indent.log&#39;</span> -delete

<span class="token target symbol">check</span><span class="token punctuation">:</span>                    <span class="token comment"># 只检查不覆盖（CI 里常用）</span>
	<span class="token operator">@</span>for f in <span class="token variable">$</span><span class="token punctuation">(</span>TEXFILES<span class="token punctuation">)</span><span class="token punctuation">;</span> do \\
	  <span class="token variable">$</span><span class="token punctuation">(</span>LATEXINDENT<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>INDENT_ARGS<span class="token punctuation">)</span> <span class="token string">&quot;$$f&quot;</span><span class="token punctuation">;</span> \\
	  diff -q <span class="token string">&quot;$$f&quot;</span> <span class="token string">&quot;$\${f%.tex}-indent.log&quot;</span> &gt;/dev/null <span class="token operator">|</span><span class="token operator">|</span> echo <span class="token string">&quot;DIFF: $$f&quot;</span><span class="token punctuation">;</span> \\
	done

<span class="token target symbol">pdf</span><span class="token punctuation">:</span>                      <span class="token comment"># 格式化后走 tectonic 编译</span>
	<span class="token variable">$</span><span class="token punctuation">(</span>LATEXINDENT<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>INDENT_ARGS<span class="token punctuation">)</span> -w main.tex
	tectonic -X compile main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-ci-集成-github-actions-示例" tabindex="-1"><a class="header-anchor" href="#_7-5-ci-集成-github-actions-示例" aria-hidden="true">#</a> 7.5 CI 集成（GitHub Actions 示例）</h3><p>在 CI 里做&quot;格式校验&quot;，不通过的提交直接报红：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/format-check.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> latexindent<span class="token punctuation">-</span>check
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">,</span> pull_request<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">check</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install latexindent
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          sudo apt-get update
          sudo apt-get install -y latexindent</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Verify formatting
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          # 对每个 tex 生成格式化结果并 diff，有差异则退出码非 0
          find . -name &#39;*.tex&#39; -print0 | while IFS= read -r -d &#39;&#39; f; do
            latexindent -s -m -l localSettings.yaml &quot;$f&quot;
            diff -q &quot;$f&quot; &quot;\${f%.tex}-indent.log&quot; \\
              || { echo &quot;需要格式化: $f&quot;; exit 1; }
          done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：在 <code>pre-commit</code> 阶段用同一套 <code>diff</code> 逻辑，让开发者本地就能自查，减少 CI 被打回。</p></blockquote><h3 id="_7-6-批量处理与生产级实践" tabindex="-1"><a class="header-anchor" href="#_7-6-批量处理与生产级实践" aria-hidden="true">#</a> 7.6 批量处理与生产级实践</h3><p><strong>批量格式化目录树（含子目录，跳过 <code>build/</code>）</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 find + 并行，处理大型项目更快</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.tex&#39;</span> <span class="token parameter variable">-not</span> <span class="token parameter variable">-path</span> <span class="token string">&#39;./build/*&#39;</span> <span class="token parameter variable">-print0</span> <span class="token punctuation">\\</span>
  <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> <span class="token parameter variable">-P</span> <span class="token number">4</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>配合 pandoc 转换工作流</strong>：pandoc 生成或他人提交的 <code>.tex</code> 格式往往不统一，先 latexindent 再进主项目：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 pandoc 从 Markdown 生成 .tex，再格式化到项目规范</span>
pandoc chapter.md <span class="token parameter variable">-o</span> chapter.tex
latexindent <span class="token parameter variable">-s</span> <span class="token parameter variable">-m</span> <span class="token parameter variable">-l</span> localSettings.yaml <span class="token parameter variable">-w</span> chapter.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>生产级建议清单</strong>：</p><ul><li>项目根目录固定一份 <code>localSettings.yaml</code>，团队统一引用；</li><li>所有脚本统一 <code>-s -m -l localSettings.yaml</code> 参数组合，避免各人写法漂移；</li><li>提交前 <code>git diff --stat</code> 检查改动规模；</li><li>在 CI 用只校验（<code>diff</code> 不覆盖）策略，代替直接 <code>-w</code> 覆盖，防止线上被悄悄改写；</li><li>对 <code>verbatim</code>、<code>minted</code>、算法环境显式放行，防止源码被误格式化。</li></ul>`,82),d=[i];function l(o,c){return e(),a("div",null,d)}const u=n(t,[["render",l],["__file","latexindent.html.vue"]]);export{u as default};
